'use strict';

/* eslint-disable n/no-unsupported-features/es-syntax -- RAB checks run conditionally only when the host exposes resize; ordinary buffer calls retain the proposed pure-JS Node8 floor. */

/* eslint n/no-unsupported-features/es-builtins: ["error", {"version": ">=8.0.0"}] */

/* eslint n/no-unsupported-features/es-syntax: ["error", {"version": ">=8.0.0"}] */


// MODULES //

var tape = require( 'tape' );
var SharedArrayBuffer = require( '@stdlib/array/shared-buffer' );
var Proxy = require( '@stdlib/proxy/ctor' );
var ArrayBuffer = require( '@stdlib/array/buffer' );
var Int32Array = require( '@stdlib/array/int32' );
var Float64Array = require( '@stdlib/array/float64' );
var main = require( './../lib/main.js' );
var dgbtf2 = require( './../lib' );
var factory = require( './../lib/factory.js' );
var eligible = require( './../lib/can_use_native.js' );


// TESTS //

tape('dgbtf2: complete scalar validation before no-access empty', function test(t) {
	[
		main,
		dgbtf2
	].forEach(function each(f) {
		var trap;
		trap = new Proxy({}, {
			'get': function get() {
				throw new Error('inactive argument read');
			}
		});
		t.strictEqual(f('column-major', 0, 3, 2147483647, 2147483647, trap, 6442450942, trap), 0, 'wide empty before backend casts or buffers');
		t.strictEqual(f.ndarray(5, 0, 1, 1, trap, trap, trap, trap, trap, trap, trap), 0, 'nd empty before inactive metadata');
		t.throws(function bad() {
			f('bad', 0, 0, 0, 0, null, 1, null);
		}, TypeError, 'layout validated');
		t.throws(function bad() {
			f('column-major', 2147483648, 0, 0, 0, null, 1, null);
		}, RangeError, 'quartet cap validated');
		t.throws(function bad() {
			f('column-major', 0, 0, 2, 1, null, 5, null);
		}, RangeError, 'LDAB validated even empty');
	});
	t.end();
});
tape('dgbtf2: rejection preserves all active backing bytes', function test(t) {
	[
		main,
		dgbtf2
	].forEach(function each(f) {
		var beforePiv;
		var before;
		var shared;
		var piv;
		var ab;
		ab = new Float64Array([
			11,
			12,
			13,
			14,
			15,
			16,
			17,
			18,
			19
		]);
		piv = new Int32Array([
			91,
			92,
			93
		]);
		before = Array.prototype.slice.call(ab);
		beforePiv = Array.prototype.slice.call(piv);
		shared = new ArrayBuffer(64);
		t.throws(function bad() {
			f.ndarray(3, 3, 1, 0, ab, 0, 3, 0, piv, 1, 0);
		}, RangeError, 'broadcast rejects');
		t.throws(function bad() {
			f.ndarray(3, 3, 1, 0, ab, 1, 1, 0, piv, 1, 0);
		}, RangeError, 'colliding full view rejects');
		t.throws(function bad() {
			f.ndarray(3, 3, 1, 0, ab, 1, 3, 1, piv, 1, 0);
		}, RangeError, 'capacity rejects');
		t.throws(function bad() {
			f.ndarray(3, 3, 1, 0, ab, 1, 3, 0, piv, 0, 0);
		}, RangeError, 'pivot broadcast rejects');
		t.deepEqual(Array.prototype.slice.call(ab), before, 'AB unchanged');
		t.deepEqual(Array.prototype.slice.call(piv), beforePiv, 'PIV unchanged');
		t.throws(function bad() {
			f('column-major', 2, 2, 0, 0, new Float64Array(shared, 0, 2), 1, new Int32Array(shared, 0, 2));
		}, RangeError, 'cross-type byte overlap rejects');
		if ((typeof SharedArrayBuffer === 'function')) {
			t.throws(function bad() {
				f('column-major', 1, 1, 0, 0, new Float64Array(new SharedArrayBuffer(8)), 1, new Int32Array(1));
			}, TypeError, 'SAB rejects');
		}
	});
	t.end();
});
tape('dgbtf2: ordinary RAB current extent and intrinsic metadata', function test(t) {
	var buffer;
	var piv;
	var ab;
	buffer = new ArrayBuffer(16, {
		'maxByteLength': 32
	});
	ab = new Float64Array(buffer);
	piv = new Int32Array(1);
	Object.defineProperty(ab, 'length', {
		'get': function get() {
			throw new Error('shadow length accessed');
		}
	});
	ab[0] = 7;
	t.strictEqual(dgbtf2('column-major', 1, 1, 0, 0, ab, 1, piv), 0, 'intrinsic length ignores shadow');
	if ((typeof buffer.resize === 'function')) {
		buffer.resize(0);
		t.throws(function bad() {
			dgbtf2('column-major', 1, 1, 0, 0, ab, 1, piv);
		}, RangeError, 'shrunk RAB rejected before write');
		buffer.resize(16);
		ab[0] = 9;
		t.strictEqual(dgbtf2('column-major', 1, 1, 0, 0, ab, 1, piv), 0, 'grown current RAB accepted');
	}
	t.end();
});
tape('dgbtf2: normalized singleton and conservative predispatch fallback', function test(t) {
	var fallback;
	var calls;
	var piv;
	var ab;
	var f;
	calls = 0;
	fallback = 0;
	f = factory(function backend() {
		calls += 1;
		return 0;
	}, function no() {
		return false;
	}, function js() {
		fallback += 1;
		return 0;
	});
	ab = new Float64Array([3]);
	piv = new Int32Array(1);
	t.strictEqual(f.ndarray(1, 1, 0, 0, ab, 9007199254740991, -9007199254740991, 0, piv, 9007199254740991, 0), 0, 'wide unused singleton validated before normalization');
	t.strictEqual(calls, 0, 'ineligible backend never called');
	t.strictEqual(fallback, 1, 'valid call falls back before native');
	t.strictEqual(f.ndarray(0, 1, 0, 0, null, null, null, null, null, null, null), 0, 'empty never dispatches');
	t.strictEqual(fallback, 1, 'empty does not reach fallback either');
	t.strictEqual(eligible(1, 1, 0, 0, ab, 1, 1, 0, piv, 1, 0), true, 'normalized tiny native domain');
	t.end();
});
